#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

static const char *p;

static void skip_ws(void) {
    while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r' || *p == ',') p++;
}

static int read_int(void) {
    skip_ws();
    int sign = 1, value = 0;
    if (*p == '-') { sign = -1; p++; }
    while (*p >= '0' && *p <= '9') {
        value = value * 10 + (*p - '0');
        p++;
    }
    return value * sign;
}

static int *parse_int_array(int *size) {
    skip_ws();
    if (*p == '[') p++;
    int cap = 4, n = 0;
    int *a = (int *)malloc(cap * sizeof(int));
    while (1) {
        skip_ws();
        if (*p == ']') { p++; break; }
        if (n == cap) {
            cap *= 2;
            a = (int *)realloc(a, cap * sizeof(int));
        }
        a[n++] = read_int();
        skip_ws();
    }
    *size = n;
    return a;
}

static int **parse_matrix(int *rows, int **cols) {
    skip_ws();
    if (*p == '[') p++;
    int row_cap = 16, r = 0;
    int **mat = (int **)malloc(row_cap * sizeof(int *));
    *cols = (int *)malloc(row_cap * sizeof(int));

    while (1) {
        skip_ws();
        if (*p == ']') { p++; break; }
        int n = 0;
        int *row = parse_int_array(&n);
        if (r == row_cap) {
            row_cap *= 2;
            mat = (int **)realloc(mat, row_cap * sizeof(int *));
            *cols = (int *)realloc(*cols, row_cap * sizeof(int));
        }
        mat[r] = row;
        (*cols)[r] = n;
        r++;
        skip_ws();
    }
    *rows = r;
    return mat;
}

bool hasPath(int **maze, int mazeSize, int *mazeColSize,
            int *start, int startSize, int *destination, int destinationSize) {
    (void)startSize;
    (void)destinationSize;
    int rows = mazeSize, cols = mazeColSize[0];
    int total = rows * cols;
    int *qx = (int *)malloc(total * sizeof(int));
    int *qy = (int *)malloc(total * sizeof(int));
    bool *visited = (bool *)calloc((size_t)total, sizeof(bool));
    int head = 0, tail = 0;
    int dx[4] = {-1, 0, 1, 0};
    int dy[4] = {0, 1, 0, -1};

    qx[tail] = start[0];
    qy[tail++] = start[1];
    visited[start[0] * cols + start[1]] = true;

    while (head < tail) {
        int x = qx[head], y = qy[head++];
        if (x == destination[0] && y == destination[1]) {
            free(qx); free(qy); free(visited);
            return true;
        }
        for (int d = 0; d < 4; ++d) {
            int nx = x, ny = y;
            while (nx + dx[d] >= 0 && nx + dx[d] < rows &&
                   ny + dy[d] >= 0 && ny + dy[d] < cols &&
                   maze[nx + dx[d]][ny + dy[d]] == 0) {
                nx += dx[d];
                ny += dy[d];
            }
            int idx = nx * cols + ny;
            if (!visited[idx]) {
                visited[idx] = true;
                qx[tail] = nx;
                qy[tail++] = ny;
            }
        }
    }

    free(qx); free(qy); free(visited);
    return false;
}

